import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
        except StopIteration:
            break

        if K > N:
            results.append("-1")
            continue

        P = [0] * (N + 1)

        for i in range(1, K + 1):
            P[i] = i

        remaining = list(range(K + 1, N + 1))

        if len(remaining) > 0:
            start_idx = K + 1
            for idx in range(start_idx, N + 1):
                val = remaining.pop(0)
                P[idx] = val

        perm_output = P[1:]
        count = 0
        for i in range(1, N + 1):
            if perm_output[i - 1] % i == 0:
                count += 1

        if count != K:
            P = [0] * (N + 1)
            for i in range(1, K + 1):
                P[i] = i
            remaining = list(range(K + 1, N + 1))

            if len(remaining) > 0:
                start_idx = K + 1
                shift = 1
                while True:
                    current_perm = [0] * (N + 1)
                    for i in range(1, K + 1):
                        current_perm[i] = i
                    rem_list = list(range(K + 1, N + 1))
                    if len(rem_list) > 0:
                        rotated = rem_list[-shift:] + rem_list[:-shift]
                        for idx in range(start_idx, N + 1):
                            current_perm[idx] = rotated[idx - start_idx]

                    cnt = 0
                    for i in range(1, N + 1):
                        if current_perm[i] % i == 0:
                            cnt += 1
                    if cnt == K:
                        P = current_perm
                        break
                    shift += 1
                    if shift >= len(remaining):
                        break
            perm_output = P[1:]

        results.append(" ".join(map(str, perm_output)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
